import { Component, h, Host, Prop, Element, Fragment, type ComponentInterface } from '@stencil/core';
import type { BreadcrumbItem, BreadcrumbDropdownItem, BreadcrumbSize } from './types';
import { KsIconChevronLeft, KsIconChevronRight, KsIconFilledChevronDown } from '@fe-infra/keystone-icons-stencil';

const prefix = 'breadcrumb';

/**
 * @part item - The breadcrumb text or link for each non-dropdown item.
 * @part base - The base container of the component.
 */
@Component({
  tag: 'ks-breadcrumb',
  styleUrl: 'ks-breadcrumb.scss',
  shadow: true,
})
export class KsBreadcrumb implements ComponentInterface {
  @Element() el!: HTMLKsBreadcrumbElement;

  /** The size of the breadcrumb component. Accepts `md` or `lg`. */
  @Prop() size: BreadcrumbSize = 'md';
  /**
   * An array of BreadcrumbItem objects that define the breadcrumb trail. Each item typically includes
   * `value` (display text), `href` (URL), `active` (boolean), and `disabled` (boolean).
   */
  @Prop() items: (BreadcrumbItem | BreadcrumbDropdownItem)[] = [];

  /** Whether to show the leading back arrow icon when there is only one breadcrumb item. */
  @Prop() showBackArrow = true;

  private renderBreadcrumbItem({ active, disabled, href, target, label, onClick }: BreadcrumbItem) {
    return (
      <li
        class={{
          [`${prefix}-item`]: true,
          [`${prefix}-item--active`]: active || false,
          [`${prefix}-item--disabled`]: disabled || false,
        }}
        onClick={!disabled && !active ? onClick : undefined}
      >
        <ks-text variant={this.size === 'lg' ? 'headlineSm' : 'labelSm'} ellipsis>
          {active ? (
            <span part="item" aria-current="page">
              {label}
            </span>
          ) : (
            <a
              target={href ? target || '_self' : undefined}
              href={disabled ? undefined : href}
              part="item"
              aria-disabled={!!disabled}
            >
              {label}
            </a>
          )}
        </ks-text>
      </li>
    );
  }

  private onDropdownItemVisibilityChange = ({ detail, target: _target }: CustomEvent<boolean>) => {
    const expandClassName = `${prefix}-item--expanded`;
    const target = _target as HTMLKsDropdownMenuElement;

    detail && !target.disabled ? target.classList.add(expandClassName) : target.classList.remove(expandClassName);
  };

  private _filterMap = new WeakMap<BreadcrumbDropdownItem['children'], BreadcrumbDropdownItem['children']>();
  private getDropdownOptionsWithFilteredOnclick(
    options: BreadcrumbDropdownItem['children'],
  ): BreadcrumbDropdownItem['children'] {
    const cached = this._filterMap.get(options);
    if (cached) {
      return cached;
    }
    const filteredOptions = options.map((item) => ({
      ...item,
      onClick: item.active ? undefined : item.onClick,
      children: item.children
        ? this.getDropdownOptionsWithFilteredOnclick(item.children as BreadcrumbDropdownItem['children'])
        : undefined,
    }));
    this._filterMap.set(options, filteredOptions);
    return filteredOptions;
  }

  private renderBreadcrumbDropdownItem({ active, children, disabled, label, trigger }: BreadcrumbDropdownItem) {
    const options: BreadcrumbDropdownItem['children'] = this.getDropdownOptionsWithFilteredOnclick(children);
    return (
      <ks-dropdown-menu
        disabled={disabled}
        options={options}
        selectable={false}
        popupWidth={{ min: 'matchAnchor', max: 480 }}
        onKsOpenChange={this.onDropdownItemVisibilityChange}
        data-testid="ks-breadcrumb-ks-breadcrumb-83pzQj"
        {...(trigger && { partProps: { tooltip: { trigger } } })}
      >
        <div
          class={{
            [`${prefix}-item`]: true,
            [`${prefix}-item--dropdown`]: true,
            [`${prefix}-item--active`]: active || false,
            [`${prefix}-item--disabled`]: disabled || false,
          }}
        >
          <ks-text variant={this.size === 'lg' ? 'headlineSm' : 'labelSm'} ellipsis>
            {label}
          </ks-text>
          <KsIconFilledChevronDown size="12" />
        </div>
      </ks-dropdown-menu>
    );
  }

  render() {
    const { items, showBackArrow, size } = this;

    const shouldShowBackArrow = items.length === 1 && showBackArrow;
    const isBreadcrumbItemWithoutChildren = (item: BreadcrumbItem | BreadcrumbDropdownItem): item is BreadcrumbItem =>
      !('children' in item);

    return (
      <Host class="KsBreadCrumb">
        <nav
          class={{
            [prefix]: true,
            [`${prefix}--${size}`]: true,
          }}
          part="base"
          aria-label="breadcrumb"
        >
          <ol class={`${prefix}__wrapper`}>
            {shouldShowBackArrow && (
              <li class={`${prefix}__back-arrow`} aria-hidden="true">
                <KsIconChevronLeft size="14" />
              </li>
            )}

            {items.map((item, index) => (
              <Fragment>
                {isBreadcrumbItemWithoutChildren(item)
                  ? this.renderBreadcrumbItem(item)
                  : this.renderBreadcrumbDropdownItem(item)}

                {index < items.length - 1 && (
                  <li class={`${prefix}__separator`} aria-hidden="true">
                    <KsIconChevronRight size="14" />
                  </li>
                )}
              </Fragment>
            ))}
          </ol>
        </nav>
      </Host>
    );
  }
}
